import math
def priority(task, state, a=2.0, b=1.0, c=1.0):
    E = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / E
    pressure = state.queue_work / max(state.capacity * state.mean_est, 1e-6)
    q = pressure / (1.0 + max(0.0, pressure))
    over = max(0.0, ratio - b)
    if over > 0.0:
        growth = math.exp(min(50.0, max(-50.0, c * math.log(over))))
    else:
        growth = 0.0
    return (1.0 / E) * (1.0 + a * q * growth)

