import math
def priority(task, state, c=1.5, m=2.0, q=10.0, b=0.5, large=1e6):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    due = task.release + c * est
    pressure = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    if wait > c * est:
        return large + tier * (wait - c * est) / est + 1.0 / est
    if pressure > q:
        return tier / max(due - state.now, 1e-6)
    return tier * (1.0 + b * wait / est) / est

def priority(task, state, c=2.0, m=1.0, q=1.0, alpha=1.0, b=0.1, late=100.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    pressure = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    slack = task.release + c * est - state.now
    lateness = max(0.0, wait - c * est)
    spt = 1.0 / est
    edf = -slack / max(est * est, 1e-6)
    if pressure > q:
        return tier * (spt + alpha * edf + b * wait / est + late * lateness / est)
    return tier * (spt + b * wait / est)

def priority(task, state, c=2.0, m=1.0, alpha=0.5, beta=50.0, r=1.0, t_map=1.0, t_reduce=1.0, t_join=1.0, t_other=1.0, s=1.0, w=0.0):
    est = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    sla_due = task.release + c * est
    deadline = min(task.due, sla_due)
    slack = deadline - state.now
    lateness = max(0.0, wait - c * est)
    if task.task_type == 'map':
        typ = t_map
    elif task.task_type == 'reduce':
        typ = t_reduce
    elif task.task_type == 'join':
        typ = t_join
    else:
        typ = t_other
    return tier * typ * (s / est + alpha * (-slack / max(est + r * need, 1e-6)) + beta * lateness / est + 0.01 * wait / est + w * max(task.weight, 1e-6) / est)

