def priority(task, state, c=2.0, g=40.0, m=1.5, w=0.0, map_boost=1.0, reduce_boost=1.0, join_boost=1.0, other_boost=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    risk = max(0.0, wait - c * est) / est
    if task.task_type == 'reduce':
        type_mult = reduce_boost
    elif task.task_type == 'join':
        type_mult = join_boost
    elif task.task_type == 'other':
        type_mult = other_boost
    else:
        type_mult = map_boost
    tier = m if task.tenant == 'premium' else 1.0
    weight = max(task.weight, 1e-6) ** w
    boost = 1.0 + g * min(risk * risk, 1000000.0) * type_mult * tier
    return weight * boost / est

