import math
def priority(task, state, c=2.0, m=1.5, k=1.0, load_th=0.8, b=0.5, guard=1e9):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    slack_slo = c - ratio
    tier = m if task.tenant == 'premium' else 1.0
    load = state.queue_work / max(state.capacity, 1e-6)
    base = tier * task.weight / est * (1.0 + b * ratio)
    if slack_slo <= 0.0:
        return guard * (1.0 - slack_slo) + base
    if load > load_th:
        denom = max(k * (1.0 + load), 1e-6)
        return base * math.exp(-slack_slo / denom)
    else:
        due_slack = max(0.0, task.due - est - state.now)
        denom = max(k * max(state.mean_est, 1e-6), 1e-6)
        return base * math.exp(-due_slack / denom) * math.exp(-slack_slo / max(k, 1e-6))

