def priority(task, state, c=1.0, m_prem=1.0, type_map=1.0, type_reduce=1.0,
             type_join=1.0, type_other=1.0, b=0.0, rho=0.0, late_b=0.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    if task.task_type == 'map':
        tm = type_map
    elif task.task_type == 'reduce':
        tm = type_reduce
    elif task.task_type == 'join':
        tm = type_join
    else:
        tm = type_other
    tier = m_prem if task.tenant == 'premium' else 1.0
    demand = est * (1.0 + rho * max(0.0, cores - 1.0))
    base = tier * tm / max(demand, 1e-6) * (1.0 + b * ratio)
    if ratio >= c:
        return 1e12 + late_b * (ratio - c) + base
    return base

